/* ============================================================
   PDF / IMPRESSAO
   ============================================================ */
function gerarPDF() {
  const btn = document.getElementById('btn-gerar-pdf');
  if (!btn) return;
  btn.classList.add('loading');
  // Funcionalidade pendente: o setTimeout simula o tempo de geração
  // apenas para dar feedback visual, mas nenhum PDF é gerado de fato.
  setTimeout(() => {
    toast('Geracao de PDF ainda nao integrada. Use imprimir por enquanto.', 'info');
    btn.classList.remove('loading');
  }, 1800);
}

function imprimirRelatorio() {
  toast('Abrindo janela de impressao...', 'info');
  // Pequeno atraso para o toast ser percebido pelo usuário antes que o
  // diálogo de impressão do navegador (bloqueante) seja aberto.
  setTimeout(() => window.print(), 600);
}

// Exportação real: o PDF e a impressão usam os dados recebidos da API, não
// uma captura da tela administrativa.
function obterDadosExportacaoRelatorio() {
  if (RELATORIO_DATA_ERROR) {
    throw new Error('O relatório não foi carregado. Atualize os dados antes de exportar.');
  }

  const resumo = RESUMO_PONTOS || {};
  return {
    data: DATA_REFERENCIA_RELATORIO || DATA_REFERENCIA_PONTOS || '',
    periodo: formatarDataReferencia(DATA_REFERENCIA_RELATORIO || DATA_REFERENCIA_PONTOS),
    geradoPor: ADMIN?.nome || 'Administrador',
    geradoEm: new Date().toLocaleString('pt-BR'),
    presentes: Number(resumo.presentes || 0),
    ausentes: Number(resumo.ausentes || 0),
    itens: (Array.isArray(RELATORIO_PONTOS) ? RELATORIO_PONTOS : []).map((item) => ({
      nome: item.funcionario?.nome || 'Funcionário não identificado',
      cargo: item.funcionario?.cargo || 'Cargo não informado',
      entrada: item.entrada || '-',
      pausa: item.pausa || '-',
      retorno: item.retorno || '-',
      saida: item.saida || '-',
      status: item.status === 'completo' ? 'Completo' : item.status === 'ausente' ? 'Ausente' : 'Em andamento',
    })),
  };
}

function textoPdf(value) {
  const troca = { '–': '-', '—': '-', '“': '"', '”': '"', '‘': "'", '’': "'", '…': '...' };
  const texto = String(value ?? '').replace(/[–—“”‘’…]/g, (char) => troca[char]);
  let hex = '';
  for (const char of texto) {
    const codigo = char.charCodeAt(0);
    hex += (codigo <= 255 ? codigo : 63).toString(16).padStart(2, '0');
  }
  return `<${hex}>`;
}

function encurtarTextoPdf(value, limite) {
  const texto = String(value ?? '');
  return texto.length > limite ? `${texto.slice(0, limite - 3)}...` : texto;
}

function criarPdfRelatorio(relatorio) {
  const itens = relatorio.itens.length ? relatorio.itens : [{
    nome: 'Nenhum registro encontrado', cargo: '-', entrada: '-', pausa: '-', retorno: '-', saida: '-', status: '-',
  }];
  const porPagina = 24;
  const paginas = [];
  const colunas = [
    ['FUNCIONÁRIO', 40, 31], ['CARGO', 238, 18], ['ENTRADA', 370, 8], ['PAUSA', 446, 8],
    ['RETORNO', 512, 8], ['SAÍDA', 586, 8], ['STATUS', 658, 17],
  ];

  for (let inicio = 0; inicio < itens.length; inicio += porPagina) {
    const comandos = [];
    const escrever = (fonte, tamanho, x, y, valor) => comandos.push(`BT /F${fonte} ${tamanho} Tf ${x} ${y} Td ${textoPdf(valor)} Tj ET`);
    const linha = (x1, y1, x2, y2, espessura = 0.5) => comandos.push(`${espessura} w ${x1} ${y1} m ${x2} ${y2} l S`);
    const paginaItens = itens.slice(inicio, inicio + porPagina);

    comandos.push('0.05 0.18 0.38 rg', '36 536 770 28 re f', '1 1 1 rg');
    escrever(2, 15, 50, 547, 'ATestaPonto | Relatório de frequência');
    escrever(1, 9, 700, 547, `Página ${paginas.length + 1}`);
    comandos.push('0 0 0 rg');
    escrever(2, 11, 36, 510, `Período: ${relatorio.periodo}`);
    escrever(1, 9, 36, 494, `Gerado por: ${relatorio.geradoPor} em ${relatorio.geradoEm}`);
    escrever(2, 10, 410, 510, `Presentes: ${relatorio.presentes}`);
    escrever(2, 10, 520, 510, `Ausentes: ${relatorio.ausentes}`);
    comandos.push('0.93 0.95 0.97 rg', '36 462 770 20 re f', '0 0 0 rg');
    colunas.forEach(([titulo, x]) => escrever(2, 7, x + 4, 469, titulo));
    linha(36, 462, 806, 462);

    paginaItens.forEach((item, indice) => {
      const y = 445 - (indice * 16);
      const valores = [item.nome, item.cargo, item.entrada, item.pausa, item.retorno, item.saida, item.status];
      colunas.forEach(([, x, limite], colIndex) => escrever(1, 8, x + 4, y, encurtarTextoPdf(valores[colIndex], limite)));
      linha(36, y - 5, 806, y - 5, 0.25);
    });
    escrever(1, 7, 36, 26, 'Documento gerado a partir dos registros do sistema ATestaPonto.');
    paginas.push(comandos.join('\n'));
  }

  const objetos = [
    '<< /Type /Catalog /Pages 2 0 R >>',
    `<< /Type /Pages /Kids [${paginas.map((_pagina, indice) => `${5 + indice * 2} 0 R`).join(' ')}] /Count ${paginas.length} >>`,
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>',
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>',
  ];
  paginas.forEach((conteudo, indice) => {
    const paginaId = 5 + indice * 2;
    objetos.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 595] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${paginaId + 1} 0 R >>`);
    objetos.push(`<< /Length ${conteudo.length} >>\nstream\n${conteudo}\nendstream`);
  });

  let arquivo = '%PDF-1.4\n%\xE2\xE3\xCF\xD3\n';
  const offsets = [0];
  objetos.forEach((objeto, indice) => {
    offsets.push(arquivo.length);
    arquivo += `${indice + 1} 0 obj\n${objeto}\nendobj\n`;
  });
  const xref = arquivo.length;
  arquivo += `xref\n0 ${objetos.length + 1}\n0000000000 65535 f \n`;
  offsets.slice(1).forEach((offset) => { arquivo += `${String(offset).padStart(10, '0')} 00000 n \n`; });
  arquivo += `trailer\n<< /Size ${objetos.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
  return new Blob([new Uint8Array(Array.from(arquivo, (char) => char.charCodeAt(0)))], { type: 'application/pdf' });
}

function gerarPDF() {
  const btn = document.getElementById('btn-gerar-pdf');
  if (!btn) return;
  try {
    btn.classList.add('loading');
    const relatorio = obterDadosExportacaoRelatorio();
    const url = URL.createObjectURL(criarPdfRelatorio(relatorio));
    const link = document.createElement('a');
    link.href = url;
    link.download = `relatorio-frequencia-${relatorio.data || new Date().toISOString().slice(0, 10)}.pdf`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
    toast('PDF do relatório gerado com sucesso.', 'success');
  } catch (error) {
    toast(error.message || 'Não foi possível gerar o PDF do relatório.', 'error');
  } finally {
    btn.classList.remove('loading');
  }
}

function criarHtmlImpressaoRelatorio(relatorio) {
  const linhas = relatorio.itens.length ? relatorio.itens.map((item) => `
    <tr><td><strong>${escapeHtml(item.nome)}</strong><small>${escapeHtml(item.cargo)}</small></td><td>${escapeHtml(item.entrada)}</td><td>${escapeHtml(item.pausa)}</td><td>${escapeHtml(item.retorno)}</td><td>${escapeHtml(item.saida)}</td><td>${escapeHtml(item.status)}</td></tr>`).join('') :
    '<tr><td colspan="6">Nenhum registro encontrado para o período.</td></tr>';
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Relatório de frequência</title><style>
    @page { size: A4 landscape; margin: 14mm; } * { box-sizing: border-box; } body { font: 11px Arial, sans-serif; color: #172033; margin: 0; } header { border-bottom: 2px solid #0d2e61; padding-bottom: 11px; margin-bottom: 16px; } h1 { color: #0d2e61; font-size: 21px; margin: 0 0 5px; } p { color: #475569; margin: 3px 0; } .summary { display: flex; gap: 12px; margin-bottom: 16px; } .card { border: 1px solid #cbd5e1; border-radius: 4px; min-width: 130px; padding: 9px 12px; } .card b { color: #0d2e61; display: block; font-size: 16px; margin-top: 3px; } table { border-collapse: collapse; width: 100%; } thead { display: table-header-group; } th { background: #0d2e61; color: white; font-size: 10px; padding: 8px; text-align: left; } td { border-bottom: 1px solid #dbe3ed; padding: 8px; vertical-align: top; } td:not(:first-child) { white-space: nowrap; } small { color: #64748b; display: block; margin-top: 2px; } footer { color: #64748b; font-size: 9px; margin-top: 16px; }
  </style></head><body><header><h1>Relatório de frequência</h1><p><strong>Período:</strong> ${escapeHtml(relatorio.periodo)}</p><p>Gerado por ${escapeHtml(relatorio.geradoPor)} em ${escapeHtml(relatorio.geradoEm)}</p></header><section class="summary"><div class="card">Presentes<b>${relatorio.presentes}</b></div><div class="card">Ausentes<b>${relatorio.ausentes}</b></div><div class="card">Registros no relatório<b>${relatorio.itens.length}</b></div></section><table><thead><tr><th>Funcionário</th><th>Entrada</th><th>Pausa</th><th>Retorno</th><th>Saída</th><th>Status</th></tr></thead><tbody>${linhas}</tbody></table><footer>Documento gerado a partir dos registros do sistema ATestaPonto.</footer></body></html>`;
}

function imprimirRelatorio() {
  try {
    const janela = window.open('', '_blank');
    if (!janela) throw new Error('O navegador bloqueou a janela de impressão. Permita pop-ups e tente novamente.');
    janela.document.write(criarHtmlImpressaoRelatorio(obterDadosExportacaoRelatorio()));
    janela.document.close();
    janela.focus();
    window.setTimeout(() => janela.print(), 150);
  } catch (error) {
    toast(error.message || 'Não foi possível preparar a impressão.', 'error');
  }
}

/* ============================================================
   CONFIGURACOES
   ============================================================ */

function iniciarConfiguracoes() {
  const navItems = document.querySelectorAll('.settings-nav-item[data-panel]');
  if (!navItems.length) return;
  navItems.forEach((item) => {
    item.addEventListener('click', () => {
      navItems.forEach((i) => i.classList.remove('active'));
      item.classList.add('active');
      document.querySelectorAll('.settings-panel').forEach((p) => {
        p.style.display = 'none';
      });
      const target = document.getElementById(item.dataset.panel);
      if (target) target.style.display = 'block';
    });
  });
}

/* ============================================================
   AUTENTICACAO GOV.BR
   A rota real ja e protegida pelo backend com req.session.admin.
   ============================================================ */

function aplicarAdminGovbr(admin) {
  if (!admin || typeof ADMIN === 'undefined') {
    return;
  }

  ADMIN.nome = admin.nome || admin.name || ADMIN.nome;
  // Cargo fixo: nesta tela todo usuário autenticado via gov.br é tratado
  // como Administrador, independente do que a API retorne.
  ADMIN.cargo = 'Administrador';

  if (typeof renderizarPerfil === 'function') {
    renderizarPerfil();
  }

  const configAvatar = document.getElementById('config-avatar');
  const configNome = document.getElementById('config-nome');
  const configNomeField = document.getElementById('cfg-nome');
  const configEmailField = document.getElementById('cfg-email');

  if (configAvatar) configAvatar.textContent = getIniciais(ADMIN.nome);
  if (configNome) configNome.textContent = ADMIN.nome;
  if (configNomeField) configNomeField.value = ADMIN.nome;
  if (configEmailField) configEmailField.value = admin.email || '';
}

async function sincronizarSessaoAdmin() {
  const controller = new AbortController();
  const timeout = window.setTimeout(() => controller.abort(), 15000);
  try {
    const payload = await adminApiFetch('/api/admin/auth/me', {
      signal: controller.signal,
    });
    const admin = getApiData(payload)?.admin;
    if (!admin) {
      const error = new Error('Sessão administrativa inválida.');
      error.status = 401;
      throw error;
    }
    aplicarAdminGovbr(admin);
    return admin;
  } catch (error) {
    if (error?.name === 'AbortError') {
      const timeoutError = new Error('A validação da sessão demorou mais que o esperado.');
      timeoutError.status = 0;
      throw timeoutError;
    }
    throw error;
  } finally {
    window.clearTimeout(timeout);
  }
}

async function validarSessaoAdmin() {
  return sincronizarSessaoAdmin();
}

function iniciarLogoutAdmin() {
  document.querySelectorAll('.btn-logout').forEach((button) => {
    // Remove handlers antigos (inline onclick e listeners anteriores)
    // antes de anexar o novo, evitando duplicidade de logout.
    button.onclick = null;
    button.removeAttribute('onclick');
    button.addEventListener('click', (event) => {
      event.preventDefault();
      redirecionarAdminParaGovbr(
        '/auth/govbr/logout',
        'Encerrando a sessão administrativa...'
      );
    });
  });
}

/* ============================================================
   BUSCA E FILTROS - FUNCIONARIOS
   ============================================================ */

function iniciarFiltrosFuncionarios() {
  const inputBusca = document.getElementById('busca-funcionario');
  const filtroStatus = document.getElementById('filtro-status');
  const filtroCargo = document.getElementById('filtro-cargo');
  let searchTimer = null;

  const reload = () => {
    if (searchTimer) window.clearTimeout(searchTimer);
    recarregarListaFuncionarios();
  };

  if (inputBusca) {
    inputBusca.addEventListener('input', () => {
      if (searchTimer) window.clearTimeout(searchTimer);
      searchTimer = window.setTimeout(reload, 300);
    });
  }
  if (filtroStatus) filtroStatus.addEventListener('change', reload);
  if (filtroCargo) filtroCargo.addEventListener('change', reload);
}


/* --- admin/modules/09-init.js --- */
(function registrarInicializacaoAdmin() {
  if (window.__ADMIN_INIT_REGISTERED__) return;
  window.__ADMIN_INIT_REGISTERED__ = true;
  let atualizacaoPaginaId = 0;
  let inicializacaoAdminEmAndamento = false;

  function iniciarLoadingDosComponentes() {
    const seletores = [
      '.dashboard-page .stat-card',
      '.dashboard-records-panel',
      '.dashboard-presence-panel',
      '.dashboard-alerts-panel',
      '.pontos-page .stat-card',
      '.pontos-page .pontos-records-panel',
      '.reports-page .report-summary-card',
      '.reports-page .reports-chart-panel',
      '.reports-page .reports-results-panel',
      '.employees-page .employees-table-panel',
      '.employees-page #cards-funcionarios',
    ];
    return seletores
      .flatMap((seletor) => Array.from(document.querySelectorAll(seletor)))
      .map((elemento) => iniciarCarregamento(elemento, {
        tamanho: 'md',
        mensagem: 'Carregando',
      }));
  }

  function renderizarDadosAdminAtuais() {
    const existe = (selector) => Boolean(document.querySelector(selector));
    if (existe('#stat-total,#stat-ativos,#stat-presentes,#stat-ausentes,#stat-taxa,#stat-registros,#hero-presentes,#hero-ausentes,#hero-total')) renderizarStats();
    if (existe('#tbody-ultimos,#cards-ultimos-mobile')) renderizarUltimosRegistros();
    if (existe('#grafico-presenca')) renderizarGrafico();
    if (existe('#lista-alertas')) renderizarAlertas();
    if (existe('#tbody-funcionarios,#cards-funcionarios')) renderizarFuncionarios();
    if (existe('#tbody-presentes,#tbody-ausentes,#cards-presentes,#cards-ausentes')) renderizarPontosHoje();
    if (existe('#tbody-relatorio')) renderizarRelatorio();
  }

  async function atualizarDadosDaPagina(options, paginaListaFuncionarios) {
    const updateId = ++atualizacaoPaginaId;
    const carregamentos = iniciarLoadingDosComponentes();
    if (paginaListaFuncionarios) FUNCIONARIOS_LOADING = true;

    try {
      return await carregarDadosAdmin(options);
    } finally {
      if (updateId !== atualizacaoPaginaId) return;
      await Promise.all(carregamentos.map(finalizarCarregamento));
      if (paginaListaFuncionarios) FUNCIONARIOS_LOADING = false;
      renderizarDadosAdminAtuais();
    }
  }

  function iniciarRecarregamentoDeDados(options, paginaListaFuncionarios) {
    if (document.documentElement.dataset.adminDataRetryInitialized === 'true') return;
    document.documentElement.dataset.adminDataRetryInitialized = 'true';
    document.addEventListener('click', (event) => {
      const retry = event.target.closest('[data-admin-data-retry]');
      if (!retry || ADMIN_DATA_LOADING) return;
      atualizarDadosDaPagina(options, paginaListaFuncionarios);
    });
  }

  async function inicializarAdmin() {
    if (inicializacaoAdminEmAndamento) return;
    inicializacaoAdminEmAndamento = true;
    const existe = (selector) => Boolean(document.querySelector(selector));
    document.documentElement.setAttribute('data-admin-session', 'pending');
    const overlaySessao = iniciarCarregamentoGlobal({
      titulo: 'Validando acesso',
      mensagem: 'Confirmando sua sessão administrativa...',
    });

    if (existe('#topbar-time')) iniciarRelogio();
    try {
      await validarSessaoAdmin();
    } catch (error) {
      inicializacaoAdminEmAndamento = false;
      if (error.status === 401) {
        redirecionarAdminParaGovbr();
        return;
      }

      const semPermissao = error.status === 403;
      atualizarCarregamentoGlobal(overlaySessao, {
        estado: 'erro',
        titulo: semPermissao ? 'Acesso não autorizado' : 'Não foi possível validar a sessão',
        mensagem: semPermissao
          ? 'Seu perfil não possui permissão administrativa.'
          : (error.message || 'Verifique sua conexão e tente novamente.'),
        aoTentarNovamente: semPermissao ? undefined : inicializarAdmin,
        aoSair: () => redirecionarAdminParaGovbr(
          '/auth/govbr/logout',
          'Encerrando a sessão administrativa...'
        ),
      });
      return;
    }

    await finalizarCarregamentoGlobal(overlaySessao);
    document.documentElement.removeAttribute('data-admin-session');
    inicializacaoAdminEmAndamento = false;

    if (existe('#admin-avatar,#admin-firstname,#admin-role,#sb-avatar,#sb-name,#sb-role')) renderizarPerfil();
    if (existe('.btn-logout')) iniciarLogoutAdmin();
    if (existe('#menu-toggle') && existe('#sidebar')) iniciarSidebar();
    if (existe('.tab-btn[data-tab],.ui-tab[data-tab]')) iniciarTabs();

    // Cada seção de dados só é carregada se algum elemento da tela atual
    // realmente precisar dela, evitando chamadas de API desnecessárias em
    // páginas que não exibem todos os blocos (ex.: uma tela sem relatório
    // não dispara a busca do relatório).
    const precisaFuncionarios = Boolean(document.querySelector(
      '#tbody-funcionarios,#cards-funcionarios,#tbody-presentes,#tbody-ausentes,#tbody-relatorio,#tbody-ultimos,#stat-total,#form-registro,#grafico-presenca'
    ));
    const precisaPontosHoje = Boolean(document.querySelector(
      '#tbody-presentes,#tbody-ausentes,#tbody-ultimos,#stat-presentes,#count-presentes,#tbody-funcionarios,#grafico-presenca'
    ));
    const precisaResumo = Boolean(document.querySelector(
      '#stat-total,#hero-presentes,#relatorio-presentes,#grafico-presenca'
    ));
    const precisaRelatorio = Boolean(document.getElementById('tbody-relatorio'));
    const paginaListaFuncionarios = Boolean(
      document.getElementById('tbody-funcionarios')
    );

    const dataOptions = {
      includeEmployees: precisaFuncionarios,
      includeToday: precisaPontosHoje,
      includeSummary: precisaResumo,
      includeReport: precisaRelatorio,
    };
    iniciarRecarregamentoDeDados(dataOptions, paginaListaFuncionarios);
    if (precisaFuncionarios || precisaPontosHoje || precisaResumo || precisaRelatorio) {
      await atualizarDadosDaPagina(dataOptions, paginaListaFuncionarios);
    } else {
      renderizarDadosAdminAtuais();
    }

    if (existe('#busca-funcionario,#filtro-status,#filtro-cargo')) {
      iniciarFiltrosFuncionarios();
      iniciarAcoesFuncionarios();
    }
    if (existe('#form-registro')) iniciarFormRegistro();
    if (existe('.settings-nav-item[data-panel]')) iniciarConfiguracoes();

    const btnPDF = document.getElementById('btn-gerar-pdf');
    const btnImprimir = document.getElementById('btn-imprimir');
    if (btnPDF) btnPDF.addEventListener('click', gerarPDF);
    if (btnImprimir) btnImprimir.addEventListener('click', imprimirRelatorio);

    document.querySelectorAll('.ui-dialog-overlay,.modal-overlay').forEach(m => {
      m.addEventListener('click', e => { if (e.target === m) m.classList.remove('show'); });
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', inicializarAdmin, { once: true });
  } else {
    inicializarAdmin();
  }
})();


/* --- admin/modules/mobile-check.js --- */
(function () {
  'use strict';

  const MOBILE_MAX_WIDTH = 768;
  // Cada configuração define um par de visões (tabela desktop / cards mobile)
  // e só é aplicada se os elementos correspondentes existirem na página atual,
  // permitindo que o mesmo script sirva telas diferentes (funcionários, pontos).
  const PAGE_CONFIGS = [
    {
      isActive: () => document.getElementById('cards-funcionarios'),
      desktopSelectors: ['.table-desktop'],
      mobileSelectors: ['#cards-funcionarios'],
      maxWidth: 1024,
    },
    {
      isActive: () => document.querySelector('.table-desktop-p, .table-desktop-a'),
      desktopSelectors: ['.table-desktop-p, .table-desktop-a'],
      mobileSelectors: ['.cards-mobile'],
    },
  ];

  function setDisplay(selectors, displayValue) {
    selectors.forEach((selector) => {
      document.querySelectorAll(selector).forEach((element) => {
        element.style.display = displayValue;
      });
    });
  }

  function mobileCheck() {
    PAGE_CONFIGS.forEach((config) => {
      if (!config.isActive()) {
        return;
      }

      const isMobile = window.innerWidth <= (config.maxWidth || MOBILE_MAX_WIDTH);

      // 'block' para a tabela desktop e 'flex' para os cards mobile:
      // valores escolhidos conforme o layout CSS de cada elemento.
      setDisplay(config.desktopSelectors, isMobile ? 'none' : 'block');
      setDisplay(config.mobileSelectors, isMobile ? 'flex' : 'none');
    });
  }

  // Exposto globalmente para permitir chamada manual (ex.: após uma
  // renderização dinâmica que insira novos elementos na página).
  window.mobileCheck = mobileCheck;
  window.addEventListener('resize', mobileCheck);
  mobileCheck();
})();


/* --- admin/modules/settings.js --- */
(function () {
  'use strict';

  const checkIcon = '<img src="/assets/icons/check.svg" alt="" aria-hidden="true" width="18" height="18">';
  const xIcon = '<img src="/assets/icons/x.svg" alt="" aria-hidden="true" width="18" height="18">';
  // Matriz estática de permissões (Admin x Funcionário) exibida na tela de
  // configurações. Não vem de API: é definida diretamente aqui no front-end.
  const permissoes = [
    ['Dashboard geral', checkIcon, xIcon],
    ['Ver todos os pontos', checkIcon, xIcon],
    ['Bater ponto', checkIcon, checkIcon],
    ['Ver próprios pontos', checkIcon, checkIcon],
    ['Cadastrar funcionários', checkIcon, xIcon],
    ['Editar funcionários', checkIcon, xIcon],
    ['Gerar relatórios', checkIcon, xIcon],
    ['Configurações do sistema', checkIcon, xIcon],
  ];

  function renderizarTabelaPermissoes() {
    const painel = document.getElementById('panel-permissoes');
    if (!painel) {
      return;
    }

    // Localiza o cabeçalho da tabela pelo conteúdo textual das colunas
    // ('Recurso', 'Admin', 'Funcionário'), já que não há um ID ou classe
    // fixa marcando essa linha no HTML.
    const cabecalho = Array.from(painel.querySelectorAll('div')).find((element) => {
      const colunas = Array.from(element.children);
      return colunas.length === 3
        && colunas[0].textContent.trim() === 'Recurso'
        && colunas[1].textContent.trim() === 'Admin'
        && colunas[2].textContent.trim() === 'Funcionário';
    });
    const tabela = cabecalho && cabecalho.parentElement;
    // Guarda de re-renderização: evita duplicar as linhas caso esta função
    // seja chamada mais de uma vez (ex.: reabertura do painel).
    if (!tabela || tabela.dataset.permissoesRenderizadas === '1') {
      return;
    }

    cabecalho.insertAdjacentHTML('afterend', permissoes.map(([r, a, f]) => `
      <div style="display:grid;grid-template-columns:1fr 100px 100px;align-items:center;padding:12px 16px;border-bottom:1px solid color-mix(in srgb, var(--color-text-muted) 24%, transparent);font-size:14px;">
        <span style="color:var(--color-text);font-weight:500;">${r}</span>
        <span style="text-align:center;font-size:17px;">${a}</span>
        <span style="text-align:center;font-size:17px;">${f}</span>
      </div>
    `).join(''));
    tabela.dataset.permissoesRenderizadas = '1';
  }

  renderizarTabelaPermissoes();
})();


